def find_gaps(arr):
    """Find contiguous gaps (values equal to bg) between non-bg values"""
    gaps = []
    n = len(arr)
    for i in range(n):
        if arr[i] != demo_bg and i+1 < n:
            j = i + 1
            while j < n and arr[j] == demo_bg:
                gaps.append(j)
                j += 1
            if j < n:
                # Found gap from i to j-1, bounded by i and j
                pass
        elif arr[i] == demo_bg and i > 0:
            # Potential start of gap going left
            k = i - 1
            while k >= 0 and arr[k] == demo_bg:
                k -= 1
            if k >= 0 and arr[k] != demo_bg:
                # Gap exists from k+1 to i-1
                if i - 1 < n - 1:
                    m = i + 1
                    while m < n and arr[m] == demo_bg:
                        m += 1
                    if m < n and arr[m] != demo_bg:
                        pass
    return gaps

