def get_components(arr, target_color):
    """Find connected components of a specific color"""
    visited = set()
    components = []

    def bfs(r, c):
        comp = [(r, c)]
        q = [(r, c)]
        while q:
            curr_r, curr_c = q.pop(0)
            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if arr[nr, nc] == target_color and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        comp.append((nr, nc))
                        q.append((nr, nc))
        return comp

    for r in range(h):
        for c in range(w):
            if arr[r, c] == target_color and (r, c) not in visited:
                comp = bfs(r, c)
                components.append(comp)

    return components

