def manhattan(p1, p2):
    return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

def find_nearest_different(r, c, color, grid):
    """Find nearest pixel of different non-bg color"""
    min_dist = float('inf')
    nearest = None

    for rr in range(h):
        for cc in range(w):
            if grid[rr, cc] != test_bg and grid[rr, cc] != color:
                d = manhattan((r,c), (rr,cc))
                if d < min_dist:
                    min_dist = d
                    nearest = (rr, cc)
    return nearest

