for color in sorted(components_by_color.keys()):
    for i, comp in enumerate(components_by_color[color]):
        if len(comp) > 3:
            # Skip large components
            continue

        # For each cell in component, expand in one direction
        for r, c in comp:
            # Find nearest different color
            nearest = find_nearest_different(r, c, color, test_grid)
            if nearest:
                nr, nc = nearest

                # Determine expansion direction (opposite to nearest)
                dr, dc = nr - r, nc - c

                if dr == 0:
                    expand_dr, expand_dc = 0, -dc
                elif dc == 0:
                    expand_dr, expand_dc = -dr, 0
                else:
                    # Diagonal - pick axis with larger difference
                    if abs(dr) >= abs(dc):
                        expand_dr, expand_dc = -dr, 0
                    else:
                        expand_dr, expand_dc = 0, -dc

                new_r, new_c = r + expand_dr, c + expand_dc

