from collections import defaultdict, deque

def get_components(grid, color):
    visited = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r,c] == color and (r,c) not in visited:
                comp = [(r,c)]
                q = deque([(r,c)])
                while q:
                    cr, cc = q.popleft()
                    visited.add((cr, cc))
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
